syntax:
struct B2 {
    B2(double d) {  // User-defined constructor taking a double parameter
                     // The compiler generates a member function for this,
                     // which is called at runtime during object initialization.
                     // No data members means no memory allocation beyond the minimal object size.
    }
};

code_example:
#include <iostream>

struct B2 {
    B2(double) {  // Empty constructor body; compiler may inline this
    }
};

int main() {
    B2 obj(3.14);  // Invokes the constructor at runtime
    return 0;
}
